package com.xz.service.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import com.xz.domain.ResponseResult;
import com.xz.domain.entity.Article;
import com.xz.domain.entity.Category;
import com.xz.domain.vo.ArticleDetailVo;
import com.xz.domain.vo.ArticleListVo;
import com.xz.domain.vo.HotArticleVo;
import com.xz.domain.vo.PageVo;
import com.xz.mapper.ArticleMapper;
import com.xz.service.ArticleService;
import com.xz.service.CategoryService;
import com.xz.utils.BeanCopyUtils;
import org.springframework.beans.BeanUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

import static com.xz.constants.SystemConstants.ARTICLE_STATUS_NORMAL;


@Service
public class ArticleServiceImpl extends ServiceImpl<ArticleMapper, Article> implements ArticleService {
    @Autowired
    private CategoryService categoryService;
    @Override
    public ResponseResult hotArticleList() {
        //热门文章排行
        //1、新建查询条件类
        LambdaQueryWrapper<Article> queryWrapper = new LambdaQueryWrapper<>();
        //2.必须是正式文章

        queryWrapper.eq(Article::getStatus, ARTICLE_STATUS_NORMAL);
        //3.按照浏览量进行排序
        queryWrapper.orderByDesc(Article::getViewCount);
        //4.最多只查询10条记录
        Page<Article> page = new Page(1, 10);
        page(page, queryWrapper);
        //5.封装成结构体返回
        List<Article> articles = page.getRecords();

        List<HotArticleVo> articleVos = new ArrayList<>();
        for (Article article : articles) {
            HotArticleVo vo = new HotArticleVo();
            BeanUtils.copyProperties(article,vo);
            articleVos.add(vo);
        }

        return ResponseResult.okResult(articleVos);
    }

    @Override
    public ResponseResult articleList(Integer pageNum, Integer pageSize, Long categoryId) {
        //查询条件
        LambdaQueryWrapper<Article> lambdaQueryWrapper = new LambdaQueryWrapper<>();

        // 如果 有categoryId 就要 查询时要和传入的相同
        lambdaQueryWrapper.eq(Objects.nonNull(categoryId)&&categoryId>0 ,Article::getCategoryId,categoryId);

        // 状态是正式发布的
        lambdaQueryWrapper.eq(Article::getStatus, ARTICLE_STATUS_NORMAL);

        // 对isTop进行降序
        lambdaQueryWrapper.orderByDesc(Article::getIsTop);

        //分页查询
        Page<Article> page = new Page<>(pageNum,pageSize);
        page(page,lambdaQueryWrapper);

        List<Article> articles = page.getRecords();

        //查询categoryName
        for (Article article : articles) {
           Category category = categoryService.getById(article.getCategoryId());
            article.setCategoryName(category.getName());
        }
        List<ArticleListVo> articleListVos = BeanCopyUtils.copyBeanList(page.getRecords(), ArticleListVo.class);
        PageVo pageVo = new PageVo(articleListVos,page.getTotal());
        return ResponseResult.okResult(pageVo);
    }

    @Override
    public ResponseResult getArticleDetail(Long id)  {
        //根据id查询文章
        Article article = getById(id);
        //转换成vo
        ArticleDetailVo articleDetailVo =BeanCopyUtils.copyBean(article,ArticleDetailVo.class);

        //根据分类id查询分类名
        Long categoryId = article.getCategoryId();
        Category category = categoryService.getById(categoryId);
        articleDetailVo.setCategoryName(category.getName());

        //封装响应返回
        return ResponseResult.okResult(articleDetailVo);
    }


}

package com.xz.service.impl;

import com.xz.domain.ResponseResult;
import com.xz.domain.entity.LoginUser;
import com.xz.domain.entity.User;
import com.xz.domain.vo.BlogUserLoginVo;
import com.xz.domain.vo.UserInfoVo;
import com.xz.service.BlogLoginService;
import com.xz.utils.BeanCopyUtils;
import com.xz.utils.JwtUtil;
import com.xz.utils.RedisCache;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;

import java.util.Objects;

@Service
public class BlogLoginServiceImpl implements BlogLoginService {
    @Autowired
    private AuthenticationManager authenticationManager;
    @Autowired
    private RedisCache redisCache;


    @Override
    public ResponseResult login(User user) {
        //调用ProviderManager的方法进行认证
        UsernamePasswordAuthenticationToken authenticationToken = new UsernamePasswordAuthenticationToken(user.getUserName(),user.getPassword());
        Authentication authenticate = authenticationManager.authenticate(authenticationToken);
        //判断是否认证通过
        if(Objects.isNull(authenticate)){
            throw new RuntimeException("用户名或密码错误");
        }
        //获取userid，生成token
        LoginUser loginUser = (LoginUser) authenticate.getPrincipal();
        String userId = loginUser.getUser().getId().toString();
        String jwt = JwtUtil.createJWT(userId);

        //把用户信息存入redis
        redisCache.setCacheObject("bloglogin:"+userId,loginUser);
        //把token和userinfo封装返回
        UserInfoVo userInfoVo = BeanCopyUtils.copyBean(loginUser.getUser(), UserInfoVo.class);
        BlogUserLoginVo vo = new BlogUserLoginVo(jwt,userInfoVo);
        return ResponseResult.okResult(vo);

    }
}

